#!/usr/bin/env bash
# Writes apps/web/.env.local pointing ONLY at the disposable stack (no Upstash vars => rate limit
# fails open, see apps/web/src/lib/ratelimit.ts) and starts the web app on 3141.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$HERE/../../.." && pwd)"
source "$HERE/00-env.sh"
source "$UAT_ROOT/keys.env"
cat >"$REPO/apps/web/.env.local" <<EOF
# DISPOSABLE UAT STACK ONLY (127.0.0.1), generated by scripts/founder-offer-go-live/uat/02-run-web.sh
NEXT_PUBLIC_SUPABASE_URL=$UAT_API_URL
NEXT_PUBLIC_SUPABASE_ANON_KEY=$UAT_ANON_KEY
SUPABASE_URL=$UAT_API_URL
SUPABASE_SERVICE_ROLE_KEY=$UAT_SERVICE_KEY
NEXT_PUBLIC_SITE_URL=http://127.0.0.1:$UAT_WEB_PORT
EOF
cd "$REPO/apps/web"
nohup npx next dev --turbopack -p "$UAT_WEB_PORT" -H 127.0.0.1 >"$UAT_ROOT/web.log" 2>&1 &
echo $! >"$UAT_ROOT/web.pid"
for i in $(seq 1 90); do curl -fs -o /dev/null "http://127.0.0.1:$UAT_WEB_PORT/fr/fondateurs" && break; sleep 2; done
echo "web up on $UAT_WEB_PORT"
